import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { EDITOR_DIR, GRID, SAVED_AT, editorFixtures } from "../scripts/rule-graph-editor.mjs";

// E37-S01: the rule-graph editor's fixtures (E37-D05 hand-off §D). Four are generated by
// scripts/rule-graph-editor.mjs and must equal its output; all ten follow the hand-off's rules.
const read = (name) => JSON.parse(readFileSync(join(EDITOR_DIR, `${name}.json`), "utf8"));
const NAMES = [
  "s-form",
  "s-graph",
  "s-form-mismatch",
  "invalid-connect",
  "cycle",
  "orphan",
  "review-60",
  "tier-b-61",
  "over-budget-121",
  "budget-200",
];

describe("the generated rule-graph editor fixtures", () => {
  it.each(Object.entries(editorFixtures()))(
    "%s is committed as the generator writes it",
    (name, fixture) => {
      // Compared as parsed JSON, so the formatter's layout of the file does not count.
      expect(read(name)).toEqual(JSON.parse(JSON.stringify(fixture)));
    },
  );

  it("builds the same fixtures on every run (seeded, no clock)", () => {
    expect(editorFixtures()).toEqual(editorFixtures());
  });

  it("sizes the tier fixtures at the tier bounds and the benchmark at 200 nodes and about 260 edges", () => {
    const sizes = Object.fromEntries(
      ["review-60", "tier-b-61", "over-budget-121", "budget-200"].map((name) => {
        const { model } = read(name);
        return [name, [model.nodes.length, model.edges.length]];
      }),
    );
    expect(sizes).toEqual({
      "review-60": [60, 58],
      "tier-b-61": [61, 59],
      "over-budget-121": [121, 119],
      "budget-200": [200, 260],
    });
  });
});

describe("every rule-graph editor fixture", () => {
  it.each(NAMES)(
    "%s: ids n1 on, a 240-unit grid position per node, version 3, 13:42:10 UTC",
    (name) => {
      const { model, layout } = read(name);
      const ids = model.nodes.map((node) => node.id);
      expect(ids).toEqual(ids.map((_, i) => `n${i + 1}`));
      expect(Object.keys(layout.positions).sort()).toEqual([...ids].sort());
      for (const { x, y } of Object.values(layout.positions)) {
        expect([x % GRID, y % GRID]).toEqual([0, 0]);
      }
      expect(model.envelope.version).toBe(3);
      expect([model.envelope.created_at, model.envelope.updated_at]).toEqual([SAVED_AT, SAVED_AT]);
      expect(new Date(SAVED_AT / 1000).toISOString()).toBe("2026-10-24T13:42:10.000Z");
    },
  );
});
